/// The SVG elements the design's icons are drawn from (ADR 0013).
///
/// `icon_data.g.dart`, generated by tools/icons, holds every icon as a
/// const list of these. The classes mirror the SVG elements and attributes
/// the design uses, with the same names and values; tools/icons stops when
/// a re-export needs anything else.
///
/// Coordinates are in the 24 × 24 viewBox of the icon. Every element is
/// stroked with the icon colour and round caps and joins, and filled only
/// when [IconElement.filled] is true.
library;

/// One SVG element of an icon.
sealed class IconElement {
  /// Creates an element; [filled] adds a fill in the icon colour.
  const new({this.filled = false});

  /// Whether the element is also filled with the icon colour, as the SVG
  /// attribute `fill="currentColor"` (the paint dots of `palette`).
  final bool filled;
}

/// `<path d="…"/>`.
final class IconPath extends IconElement {
  /// Creates a path from its SVG path data [d].
  const new({required this.d, super.filled});

  /// The SVG path data, exactly as the design writes it.
  final String d;
}

/// `<circle cx="…" cy="…" r="…"/>`.
final class IconCircle extends IconElement {
  /// Creates a circle around ([cx], [cy]) with radius [r].
  const new({
    required this.cx,
    required this.cy,
    required this.r,
    super.filled,
  });

  /// The x coordinate of the centre.
  final double cx;

  /// The y coordinate of the centre.
  final double cy;

  /// The radius.
  final double r;
}

/// `<ellipse cx="…" cy="…" rx="…" ry="…"/>`.
final class IconEllipse extends IconElement {
  /// Creates an ellipse around ([cx], [cy]) with radii [rx] and [ry].
  const new({
    required this.cx,
    required this.cy,
    required this.rx,
    required this.ry,
    super.filled,
  });

  /// The x coordinate of the centre.
  final double cx;

  /// The y coordinate of the centre.
  final double cy;

  /// The horizontal radius.
  final double rx;

  /// The vertical radius.
  final double ry;
}

/// `<rect x="…" y="…" width="…" height="…" rx="…" ry="…"/>`.
final class IconRect extends IconElement {
  /// Creates a rectangle with its top-left corner at ([x], [y]) and
  /// optional corner radii [rx] and [ry].
  const new({
    required this.x,
    required this.y,
    required this.width,
    required this.height,
    this.rx,
    this.ry,
    super.filled,
  });

  /// The left edge.
  final double x;

  /// The top edge.
  final double y;

  /// The width.
  final double width;

  /// The height.
  final double height;

  /// The horizontal corner radius, or `null` when the design gives none.
  ///
  /// As in SVG, a missing radius takes the value of the other one, and
  /// both missing means square corners.
  final double? rx;

  /// The vertical corner radius, or `null` when the design gives none.
  final double? ry;
}

/// `<line x1="…" y1="…" x2="…" y2="…"/>`.
final class IconLine extends IconElement {
  /// Creates a line from ([x1], [y1]) to ([x2], [y2]).
  const new({
    required this.x1,
    required this.y1,
    required this.x2,
    required this.y2,
    super.filled,
  });

  /// The x coordinate of the start.
  final double x1;

  /// The y coordinate of the start.
  final double y1;

  /// The x coordinate of the end.
  final double x2;

  /// The y coordinate of the end.
  final double y2;
}

/// `<polyline points="…"/>`: an open run of straight segments.
final class IconPolyline extends IconElement {
  /// Creates a polyline through [points].
  const new({required this.points, super.filled});

  /// The SVG points list (`x,y x,y …`), exactly as the design writes it.
  /// As path data it reads `M` followed by the list.
  final String points;
}

/// `<polygon points="…"/>`: a closed run of straight segments.
final class IconPolygon extends IconElement {
  /// Creates a polygon through [points].
  const new({required this.points, super.filled});

  /// The SVG points list (`x,y x,y …`), exactly as the design writes it.
  /// As path data it reads `M`, the list and `Z`.
  final String points;
}
